// Vendas tab storage keys, read directly here (read-only) to build the comparative
// chart below — sales are recorded once per client ("c" field = codigo_cliente),
// not per order, so this reads the same stored list the Vendas tab maintains.
const VENDAS_STORAGE_KEY = "isp-sales-records-v1";

function monthKeyFromDT(dt) {
  if (!dt || typeof dt !== "string") return null;
  const m = dt.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (!m) return null;
  return `${m[3]}-${m[2]}`;
}
function monthLabel(key) {
  if (!key) return "";
  const [y, m] = key.split("-");
  return `${MESES_ABREV[parseInt(m, 10) - 1]}/${y.slice(2)}`;
}
function parseBRDateTimeToMinutes(dt) {
  if (!dt || typeof dt !== "string") return null;
  const m = dt.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
  if (!m) return null;
  const [, d, mo, y, hh, mm] = m;
  return Date.UTC(+y, +mo - 1, +d, +hh, +mm) / 60000;
}
function fmtInt(v) {
  return new Intl.NumberFormat("pt-BR").format(v || 0);
}
function fmtPct(v) {
  if (!isFinite(v)) return "—";
  return new Intl.NumberFormat("pt-BR", { style: "percent", maximumFractionDigits: 1 }).format(v);
}
function fmtHoras(v) {
  if (v === null || v === undefined || !isFinite(v)) return "—";
  return `${new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 1 }).format(v)}h`;
}

const HEADER_MAP = {
  numero_ordem_servico: "os", tipo_ordem_servico: "tp", tecnicos: "tec", status: "st",
  prioridade: "pr", data_inicio_programado: "dp_d", hora_inicio_programado: "dp_h",
  data_inicio_executado: "di_d", hora_inicio_executado: "di_h",
  data_termino_executado: "dt_d", hora_termino_executado: "dt_h",
};

function combineDateTime(d, h) {
  if (!d || d === "-") return null;
  const hh = h && h !== "-" ? h : "00:00:00";
  return `${d} ${hh}`;
}

function parseWorkbookToRecords(workbook) {
  const sheetName = workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: false, defval: "" });
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || "").trim().toLowerCase());
  const colIndex = {};
  headers.forEach((h, i) => { if (HEADER_MAP[h]) colIndex[HEADER_MAP[h]] = i; });
  const get = (row, key) => (colIndex[key] !== undefined ? row[colIndex[key]] : "");
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row.length) continue;
    const numero = get(row, "os");
    if (!numero || numero === "-") continue;
    const tipo = String(get(row, "tp") || "-") || "-";
    const tecnicos = String(get(row, "tec") || "-") || "-";
    const status = String(get(row, "st") || "-") || "-";
    const prioridade = String(get(row, "pr") || "-") || "-";
    const dp = combineDateTime(get(row, "dp_d"), get(row, "dp_h"));
    const di = combineDateTime(get(row, "di_d"), get(row, "di_h"));
    const dt_ = combineDateTime(get(row, "dt_d"), get(row, "dt_h"));
    out.push({ os: String(numero), tp: tipo, tec: tecnicos, st: status, pr: prioridade, dp, di, dt: dt_ });
  }
  return out;
}

function mergeRecords(existing, incoming) {
  const map = new Map(existing.map((r) => [r.os, r]));
  let added = 0, updated = 0;
  incoming.forEach((r) => {
    if (map.has(r.os)) updated++; else added++;
    map.set(r.os, r);
  });
  return { merged: Array.from(map.values()), added, updated };
}

function tempoExecucaoHoras(r) {
  if (r.st !== "finalizado" || !r.di || !r.dt) return null;
  const start = parseBRDateTimeToMinutes(r.di);
  const end = parseBRDateTimeToMinutes(r.dt);
  if (start === null || end === null) return null;
  const h = (end - start) / 60;
  return h >= 0 && h <= 24 ? h : null;
}

function atrasoHoras(r) {
  if (!r.dp || !r.di) return null;
  const prog = parseBRDateTimeToMinutes(r.dp);
  const exec = parseBRDateTimeToMinutes(r.di);
  if (prog === null || exec === null) return null;
  const h = (exec - prog) / 60;
  return h > -200 && h < 800 ? h : null;
}

function KpiCard({ icon: Icon, label, value, sub, accent }) {
  return (
    <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 20px", flex: "1 1 200px", minWidth: 190 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <div style={{ width: 28, height: 28, borderRadius: 7, background: accent + "1A", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Icon size={15} color={accent} strokeWidth={2.2} />
        </div>
        <span style={{ fontFamily: FONT_BODY, fontSize: 12.5, color: COLORS.inkMuted, fontWeight: 500 }}>{label}</span>
      </div>
      <div style={{ fontFamily: FONT_MONO, fontSize: 24, fontWeight: 600, color: COLORS.ink, letterSpacing: "-0.5px" }}>{value}</div>
      {sub && <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: COLORS.inkMuted, marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

function Toggle({ options, value, onChange }) {
  return (
    <div style={{ display: "inline-flex", background: COLORS.tealSoft, borderRadius: 8, padding: 3, gap: 2 }}>
      {options.map((opt) => (
        <button key={opt.value} onClick={() => onChange(opt.value)} style={{
          fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600, padding: "6px 14px", borderRadius: 6, border: "none",
          cursor: "pointer", background: value === opt.value ? COLORS.teal : "transparent",
          color: value === opt.value ? "#fff" : COLORS.tealDark, transition: "background 0.15s ease",
        }}>{opt.label}</button>
      ))}
    </div>
  );
}

function CheckboxPill({ label, checked, onClick, color }) {
  return (
    <button onClick={onClick} style={{
      display: "inline-flex", alignItems: "center", gap: 6, fontFamily: FONT_BODY, fontSize: 12.5,
      padding: "5px 10px 5px 8px", borderRadius: 7, cursor: "pointer",
      border: `1px solid ${checked ? (color || COLORS.teal) : COLORS.border}`,
      background: checked ? (color ? color + "14" : COLORS.tealSoft) : "#fff",
      color: checked ? COLORS.ink : COLORS.inkMuted, fontWeight: 500, transition: "all 0.12s ease",
    }}>
      <span style={{
        width: 14, height: 14, borderRadius: 4, border: `1.5px solid ${checked ? (color || COLORS.teal) : COLORS.borderStrong}`,
        background: checked ? (color || COLORS.teal) : "transparent", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      }}>
        {checked && <Check size={10} color="#fff" strokeWidth={3} />}
      </span>
      {label}
    </button>
  );
}

export default function OrdensServicoDashboard() {
  const [records, setRecords] = useState(null);
  const [importLog, setImportLog] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploadMsg, setUploadMsg] = useState(null);
  const [uploadError, setUploadError] = useState(null);
  const [metric, setMetric] = useState("count");
  const [tecnicoFilter, setTecnicoFilter] = useState(null);
  const [tipoFilter, setTipoFilter] = useState(null);
  const [statusFilter, setStatusFilter] = useState(null);
  const [sortCol, setSortCol] = useState("total");
  const [vendasRecords, setVendasRecords] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    (async () => {
      let recs = null, log = [];
      try {
        const res = await window.storage.get(STORAGE_KEY, false);
        if (res && res.value) recs = JSON.parse(res.value);
      } catch (e) { recs = null; }
      try {
        const res = await window.storage.get(LOG_KEY, false);
        if (res && res.value) log = JSON.parse(res.value);
      } catch (e) { log = []; }
      if (!recs) {
        recs = INITIAL_DATA;
        log = [{ date: "2026-10-02T00:00:00", label: "Base inicial", added: INITIAL_DATA.length, updated: 0 }];
        try {
          await window.storage.set(STORAGE_KEY, JSON.stringify(recs), false);
          await window.storage.set(LOG_KEY, JSON.stringify(log), false);
        } catch (e) { /* surfaced on next save attempt */ }
      }
      setRecords(recs);
      setImportLog(log);
      setLoading(false);
      try {
        const res = await window.storage.get(VENDAS_STORAGE_KEY, false);
        if (res && res.value) setVendasRecords(JSON.parse(res.value));
      } catch (e) { setVendasRecords(null); }
    })();
  }, []);

  const tecnicos = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.tec))).filter((v) => v && v !== "-").sort();
  }, [records]);
  const tipos = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.tp))).filter((v) => v && v !== "-").sort();
  }, [records]);
  const statuses = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.st))).filter((v) => v && v !== "-").sort();
  }, [records]);

  useEffect(() => { if (tecnicos.length && !tecnicoFilter) setTecnicoFilter(new Set(tecnicos)); }, [tecnicos]);
  useEffect(() => { if (tipos.length && !tipoFilter) setTipoFilter(new Set(tipos)); }, [tipos]);
  useEffect(() => { if (statuses.length && !statusFilter) setStatusFilter(new Set(statuses)); }, [statuses]);

  const filtered = useMemo(() => {
    if (!records || !tecnicoFilter || !tipoFilter || !statusFilter) return [];
    return records.filter((r) => tecnicoFilter.has(r.tec) && tipoFilter.has(r.tp) && statusFilter.has(r.st) && monthKeyFromDT(r.dp));
  }, [records, tecnicoFilter, tipoFilter, statusFilter]);

  const months = useMemo(() => {
    const set = new Set(filtered.map((r) => monthKeyFromDT(r.dp)));
    return Array.from(set).sort();
  }, [filtered]);

  const monthlyTotals = useMemo(() => {
    const map = new Map();
    months.forEach((m) => map.set(m, { month: m, count: 0, tempoSum: 0, tempoCount: 0, pontualSum: 0, pontualCount: 0, atrasoSum: 0, atrasoCount: 0 }));
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.dp);
      const e = map.get(mk);
      if (!e) return;
      e.count += 1;
      const tempo = tempoExecucaoHoras(r);
      if (tempo !== null) { e.tempoSum += tempo; e.tempoCount += 1; }
      const atraso = atrasoHoras(r);
      if (atraso !== null) {
        e.atrasoSum += atraso; e.atrasoCount += 1;
        e.pontualCount += 1;
        if (atraso <= 4) e.pontualSum += 1;
      }
    });
    return months.map((m) => {
      const e = map.get(m);
      return {
        ...e,
        tempoMedio: e.tempoCount ? e.tempoSum / e.tempoCount : null,
        atrasoMedio: e.atrasoCount ? e.atrasoSum / e.atrasoCount : null,
        taxaPontualidade: e.pontualCount ? e.pontualSum / e.pontualCount : null,
      };
    });
  }, [filtered, months]);

  const tecnicoMonthMatrix = useMemo(() => {
    const tSet = new Set(filtered.map((r) => r.tec));
    const tList = Array.from(tSet).sort();
    const data = {};
    tList.forEach((t) => {
      data[t] = { tecnico: t, totalCount: 0, totalTempoSum: 0, totalTempoCount: 0, byMonth: {} };
      months.forEach((m) => { data[t].byMonth[m] = { count: 0, tempoSum: 0, tempoCount: 0 }; });
    });
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.dp);
      if (!data[r.tec]) return;
      data[r.tec].byMonth[mk].count += 1;
      data[r.tec].totalCount += 1;
      const tempo = tempoExecucaoHoras(r);
      if (tempo !== null) {
        data[r.tec].byMonth[mk].tempoSum += tempo; data[r.tec].byMonth[mk].tempoCount += 1;
        data[r.tec].totalTempoSum += tempo; data[r.tec].totalTempoCount += 1;
      }
    });
    let rows = Object.values(data);
    const cellMetric = (row, m) => {
      const c = row.byMonth[m];
      return metric === "count" ? c.count : (c.tempoCount ? c.tempoSum / c.tempoCount : null);
    };
    const totalMetric = (row) => metric === "count" ? row.totalCount : (row.totalTempoCount ? row.totalTempoSum / row.totalTempoCount : null);
    rows.sort((a, b) => {
      if (sortCol === "tecnico") return a.tecnico.localeCompare(b.tecnico);
      if (sortCol === "total") return (totalMetric(b) || 0) - (totalMetric(a) || 0);
      return (cellMetric(b, sortCol) || 0) - (cellMetric(a, sortCol) || 0);
    });
    return rows;
  }, [filtered, months, sortCol, metric]);

  const tipoMonthMatrix = useMemo(() => {
    const mSet = new Set(filtered.map((r) => r.tp));
    const mList = Array.from(mSet).sort((a, b) => {
      const ca = filtered.filter((r) => r.tp === a).length;
      const cb = filtered.filter((r) => r.tp === b).length;
      return cb - ca;
    });
    const data = {};
    mList.forEach((tp) => {
      data[tp] = { tipo: tp, totalCount: 0, byMonth: {} };
      months.forEach((m) => { data[tp].byMonth[m] = 0; });
    });
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.dp);
      if (!data[r.tp]) return;
      data[r.tp].byMonth[mk] += 1;
      data[r.tp].totalCount += 1;
    });
    return Object.values(data);
  }, [filtered, months]);

  const kpis = useMemo(() => {
    if (!months.length) return null;
    const currentMonth = months[months.length - 1];
    const curEntry = monthlyTotals.find((m) => m.month === currentMonth) || { count: 0, tempoMedio: null, taxaPontualidade: null };
    const tempos = filtered.map(tempoExecucaoHoras).filter((v) => v !== null);
    const tempoMedioGeral = tempos.length ? tempos.reduce((s, v) => s + v, 0) / tempos.length : null;
    const porTecnico = {};
    filtered.forEach((r) => { if (r.tec !== "-") porTecnico[r.tec] = (porTecnico[r.tec] || 0) + 1; });
    const top = Object.entries(porTecnico).sort((a, b) => b[1] - a[1])[0];
    return {
      currentMonth, curCount: curEntry.count, taxaPontualidade: curEntry.taxaPontualidade,
      tempoMedioGeral, topTecnico: top ? top[0] : "—", topCount: top ? top[1] : 0,
    };
  }, [months, monthlyTotals, filtered]);

  const grandTotal = useMemo(() => {
    const count = filtered.length;
    const byMonth = {};
    months.forEach((m) => { byMonth[m] = monthlyTotals.find((x) => x.month === m) || { count: 0 }; });
    return { count, byMonth };
  }, [filtered, months, monthlyTotals]);

  // Comparativo: vendas fechadas vs instalações executadas, por mês — mostra se a
  // instalação em campo está acompanhando o ritmo de vendas ou formando fila.
  const vendasVsInstalacoes = useMemo(() => {
    if (!vendasRecords) return null;
    const vendasPorMes = {};
    vendasRecords.forEach((v) => {
      if (!v.dv) return;
      const m = v.dv.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
      if (!m) return;
      const key = `${m[3]}-${m[2]}`;
      vendasPorMes[key] = (vendasPorMes[key] || 0) + 1;
    });
    const instalacoesPorMes = {};
    (records || []).forEach((r) => {
      if (r.st !== "finalizado" || !/INSTALA/i.test(r.tp)) return;
      const ref = r.dt || r.di || r.dp;
      const mk = monthKeyFromDT(ref);
      if (!mk) return;
      instalacoesPorMes[mk] = (instalacoesPorMes[mk] || 0) + 1;
    });
    const allMonths = Array.from(new Set([...Object.keys(vendasPorMes), ...Object.keys(instalacoesPorMes)])).sort();
    return allMonths.map((m) => ({
      month: m, label: monthLabel(m),
      vendas: vendasPorMes[m] || 0, instalacoes: instalacoesPorMes[m] || 0,
    }));
  }, [vendasRecords, records]);

  const handleFile = useCallback(async (file) => {
    setUploadMsg(null); setUploadError(null);
    try {
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: "array" });
      const parsed = parseWorkbookToRecords(wb);
      if (!parsed.length) {
        setUploadError("Não encontrei linhas reconhecíveis nesse arquivo. Confira se é uma exportação do mesmo relatório de ordens de serviço.");
        return;
      }
      const { merged, added, updated } = mergeRecords(records || [], parsed);
      const newLog = [{ date: new Date().toISOString(), label: file.name, added, updated }, ...importLog].slice(0, 20);
      try {
        await window.storage.set(STORAGE_KEY, JSON.stringify(merged), false);
        await window.storage.set(LOG_KEY, JSON.stringify(newLog), false);
      } catch (e) {
        setUploadError("Não consegui salvar no banco (" + (e && e.message ? e.message : "erro desconhecido") + ").");
        return;
      }
      setRecords(merged);
      setImportLog(newLog);
      setUploadMsg(`Importado: ${added} novo(s), ${updated} atualizado(s).`);
    } catch (e) {
      setUploadError("Não consegui ler esse arquivo. Confira se é um .xlsx exportado do sistema.");
    }
  }, [records, importLog]);

  const handleReset = useCallback(async () => {
    if (!window.confirm("Isso vai apagar os relatórios importados e voltar para a base inicial. Continuar?")) return;
    const log = [{ date: "2026-10-02T00:00:00", label: "Base inicial", added: INITIAL_DATA.length, updated: 0 }];
    try {
      await window.storage.set(STORAGE_KEY, JSON.stringify(INITIAL_DATA), false);
      await window.storage.set(LOG_KEY, JSON.stringify(log), false);
    } catch (e) { setUploadError("Não consegui salvar no banco."); return; }
    setRecords(INITIAL_DATA);
    setImportLog(log);
  }, []);

  if (loading || !records) {
    return <div style={{ fontFamily: FONT_BODY, padding: 40, color: COLORS.inkMuted }}>Carregando painel…</div>;
  }

  const barData = monthlyTotals.map((m) => ({ ...m, label: monthLabel(m.month) }));

  return (
    <div style={{ fontFamily: FONT_BODY, color: COLORS.ink }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 16, marginBottom: 26 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
            <div style={{ width: 34, height: 34, borderRadius: 8, background: COLORS.teal, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              <Wrench size={18} color="#fff" strokeWidth={2.3} />
            </div>
            <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 600, margin: 0, letterSpacing: "-0.3px" }}>Painel de ordens de serviço</h1>
          </div>
          <p style={{ fontFamily: FONT_BODY, fontSize: 13, color: COLORS.inkMuted, margin: 0 }}>
            {fmtInt(records.length)} ordens de serviço na base {importLog[0] ? `· atualizado em ${new Date(importLog[0].date).toLocaleDateString("pt-BR")}` : ""}
          </p>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <button onClick={handleReset} title="Restaurar base inicial" style={{
            display: "flex", alignItems: "center", gap: 6, fontFamily: FONT_BODY, fontSize: 12.5, fontWeight: 500,
            padding: "9px 12px", borderRadius: 8, border: `1px solid ${COLORS.border}`, background: "#fff", color: COLORS.inkMuted, cursor: "pointer",
          }}><RotateCcw size={13} /> Restaurar</button>
          <button onClick={() => fileInputRef.current && fileInputRef.current.click()} style={{
            display: "flex", alignItems: "center", gap: 7, fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600,
            padding: "9px 16px", borderRadius: 8, border: "none", background: COLORS.teal, color: "#fff", cursor: "pointer",
          }}><Upload size={14} /> Atualizar relatório</button>
          <input ref={fileInputRef} type="file" accept=".xlsx,.xls" style={{ display: "none" }}
            onChange={(e) => { const f = e.target.files && e.target.files[0]; if (f) handleFile(f); e.target.value = ""; }} />
        </div>
      </div>

      {(uploadMsg || uploadError) && (
        <div style={{
          marginBottom: 18, padding: "10px 14px", borderRadius: 8, fontSize: 13, fontFamily: FONT_BODY,
          background: uploadError ? COLORS.redSoft : COLORS.greenSoft, color: uploadError ? COLORS.red : COLORS.green,
          display: "flex", alignItems: "center", gap: 8,
        }}><Info size={14} /> {uploadError || uploadMsg}</div>
      )}

      {kpis && (
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 22 }}>
          <KpiCard icon={Wrench} accent={COLORS.teal} label={`OS em ${monthLabel(kpis.currentMonth)}`} value={fmtInt(kpis.curCount)} sub="ordens de serviço no mês mais recente" />
          <KpiCard icon={Timer} accent={COLORS.green} label="Pontualidade do mês" value={fmtPct(kpis.taxaPontualidade)} sub="iniciadas em até 4h do horário agendado" />
          <KpiCard icon={Clock} accent={COLORS.amber} label="Tempo médio de execução" value={fmtHoras(kpis.tempoMedioGeral)} sub="do início ao término, no filtro atual" />
          <KpiCard icon={Award} accent={COLORS.tealDark} label="Técnico mais atarefado" value={kpis.topTecnico} sub={`${fmtInt(kpis.topCount)} ordens no filtro atual`} />
        </div>
      )}

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "14px 16px", marginBottom: 22, display: "flex", flexWrap: "wrap", gap: 18, alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Técnico(s)</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 480 }}>
            {tecnicos.map((v) => (
              <CheckboxPill key={v} label={v} checked={tecnicoFilter && tecnicoFilter.has(v)}
                onClick={() => setTecnicoFilter((prev) => { const next = new Set(prev); next.has(v) ? next.delete(v) : next.add(v); return next; })} />
            ))}
          </div>
        </div>
        <div style={{ width: 1, alignSelf: "stretch", background: COLORS.border }} />
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Status</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 320 }}>
            {statuses.map((s) => (
              <CheckboxPill key={s} label={s} checked={statusFilter && statusFilter.has(s)}
                color={s === "finalizado" ? COLORS.green : s === "pendente" ? COLORS.red : COLORS.amber}
                onClick={() => setStatusFilter((prev) => { const next = new Set(prev); next.has(s) ? next.delete(s) : next.add(s); return next; })} />
            ))}
          </div>
        </div>
        <div style={{ width: 1, alignSelf: "stretch", background: COLORS.border }} />
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Tipo de OS</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 480, maxHeight: 90, overflowY: "auto" }}>
            {tipos.map((t) => (
              <CheckboxPill key={t} label={t} checked={tipoFilter && tipoFilter.has(t)}
                onClick={() => setTipoFilter((prev) => { const next = new Set(prev); next.has(t) ? next.delete(t) : next.add(t); return next; })} />
            ))}
          </div>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.1fr 1fr", gap: 16, marginBottom: 24 }}>
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 8px" }}>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Ordens de serviço por mês</div>
          <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 10 }}>Volume total, todos os meses da base</div>
          <ResponsiveContainer width="100%" height={230}>
            <BarChart data={barData} margin={{ top: 4, right: 8, left: -18, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
              <XAxis dataKey="label" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: COLORS.inkMuted }} axisLine={{ stroke: COLORS.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip formatter={(v) => [fmtInt(v), "Ordens"]} contentStyle={{ fontFamily: FONT_BODY, fontSize: 12.5, borderRadius: 8, border: `1px solid ${COLORS.border}` }} />
              <Bar dataKey="count" fill={COLORS.teal} radius={[5, 5, 0, 0]} maxBarSize={44} />
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 8px" }}>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Pontualidade e tempo médio</div>
          <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 10 }}>% iniciado em até 4h do agendado (linha) e horas médias de execução, por mês</div>
          <ResponsiveContainer width="100%" height={230}>
            <LineChart data={barData} margin={{ top: 4, right: 8, left: -8, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
              <XAxis dataKey="label" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: COLORS.inkMuted }} axisLine={{ stroke: COLORS.border }} tickLine={false} />
              <YAxis yAxisId="pct" tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} tickFormatter={(v) => `${Math.round(v * 100)}%`} width={40} />
              <YAxis yAxisId="h" orientation="right" tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} width={40} />
              <Tooltip formatter={(v, name) => name === "taxaPontualidade" ? [fmtPct(v), "Pontualidade"] : [fmtHoras(v), "Tempo médio"]}
                contentStyle={{ fontFamily: FONT_BODY, fontSize: 12.5, borderRadius: 8, border: `1px solid ${COLORS.border}` }} />
              <Line yAxisId="pct" type="monotone" dataKey="taxaPontualidade" stroke={COLORS.green} strokeWidth={2.4} dot={{ r: 3.5, fill: COLORS.green }} />
              <Line yAxisId="h" type="monotone" dataKey="tempoMedio" stroke={COLORS.amber} strokeWidth={2.4} dot={{ r: 3.5, fill: COLORS.amber }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 20px", marginBottom: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
          <div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600 }}>Técnico × mês</div>
            <div style={{ fontSize: 12, color: COLORS.inkMuted }}>Clique em uma coluna para ordenar</div>
          </div>
          <Toggle value={metric} onChange={setMetric} options={[{ value: "count", label: "Ordens" }, { value: "tempo", label: "Tempo médio" }]} />
        </div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: FONT_BODY, fontSize: 13, minWidth: 640 }}>
            <thead>
              <tr>
                <th onClick={() => setSortCol("tecnico")} style={{ textAlign: "left", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>
                  Técnico <ArrowUpDown size={10} style={{ display: "inline", marginLeft: 2, verticalAlign: -1 }} />
                </th>
                {months.map((m) => (
                  <th key={m} onClick={() => setSortCol(m)} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>
                    {monthLabel(m)}
                  </th>
                ))}
                <th onClick={() => setSortCol("total")} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.ink, fontWeight: 700, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>Total</th>
              </tr>
            </thead>
            <tbody>
              {tecnicoMonthMatrix.map((row, i) => (
                <tr key={row.tecnico} style={{ background: i % 2 === 1 ? COLORS.bg : "transparent" }}>
                  <td style={{ padding: "8px 10px", fontWeight: 500, whiteSpace: "nowrap" }}>{row.tecnico}</td>
                  {months.map((m) => {
                    const c = row.byMonth[m];
                    const val = metric === "count" ? c.count : (c.tempoCount ? c.tempoSum / c.tempoCount : null);
                    return (
                      <td key={m} style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, color: val ? COLORS.ink : COLORS.inkMuted }}>
                        {metric === "count" ? (val || "–") : fmtHoras(val)}
                      </td>
                    );
                  })}
                  <td style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 600, color: COLORS.tealDark }}>
                    {metric === "count" ? fmtInt(row.totalCount) : fmtHoras(row.totalTempoCount ? row.totalTempoSum / row.totalTempoCount : null)}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr>
                <td style={{ padding: "9px 10px", fontWeight: 700, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>Total</td>
                {months.map((m) => {
                  const e = grandTotal.byMonth[m] || { count: 0 };
                  return (
                    <td key={m} style={{ padding: "9px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 700, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>
                      {metric === "count" ? fmtInt(e.count) : fmtHoras(e.tempoMedio)}
                    </td>
                  );
                })}
                <td style={{ padding: "9px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 700, color: COLORS.tealDark, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>
                  {metric === "count" ? fmtInt(grandTotal.count) : "—"}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 20px", marginBottom: 20 }}>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Tipo de OS × mês</div>
        <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 14 }}>Quantidade de ordens por tipo de serviço, mês a mês</div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: FONT_BODY, fontSize: 13, minWidth: 640 }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12 }}>Tipo de OS</th>
                {months.map((m) => (
                  <th key={m} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, whiteSpace: "nowrap" }}>{monthLabel(m)}</th>
                ))}
                <th style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.ink, fontWeight: 700, fontSize: 12 }}>Total</th>
              </tr>
            </thead>
            <tbody>
              {tipoMonthMatrix.map((row, i) => (
                <tr key={row.tipo} style={{ background: i % 2 === 1 ? COLORS.bg : "transparent" }}>
                  <td style={{ padding: "8px 10px", fontWeight: 500 }}>{row.tipo}</td>
                  {months.map((m) => (
                    <td key={m} style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, color: row.byMonth[m] ? COLORS.ink : COLORS.inkMuted }}>
                      {row.byMonth[m] || "–"}
                    </td>
                  ))}
                  <td style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 600, color: COLORS.tealDark }}>{fmtInt(row.totalCount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {vendasVsInstalacoes && vendasVsInstalacoes.length > 0 && (
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 8px", marginBottom: 20 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 2 }}>
            <TrendingUp size={14} color={COLORS.inkMuted} />
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600 }}>Comparativo: vendas vs instalações executadas</div>
          </div>
          <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 10 }}>
            Vendas fechadas (aba Vendas) contra instalações de fato concluídas em campo (OS do tipo "Instalação", finalizadas), por mês — mostra se a instalação está acompanhando o ritmo de vendas ou formando fila.
          </div>
          <ResponsiveContainer width="100%" height={230}>
            <BarChart data={vendasVsInstalacoes} margin={{ top: 4, right: 8, left: -18, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
              <XAxis dataKey="label" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: COLORS.inkMuted }} axisLine={{ stroke: COLORS.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip formatter={(v, name) => [fmtInt(v), name === "vendas" ? "Vendas" : "Instalações executadas"]}
                contentStyle={{ fontFamily: FONT_BODY, fontSize: 12.5, borderRadius: 8, border: `1px solid ${COLORS.border}` }} />
              <Bar dataKey="vendas" fill={COLORS.teal} radius={[5, 5, 0, 0]} maxBarSize={30} />
              <Bar dataKey="instalacoes" fill={COLORS.amber} radius={[5, 5, 0, 0]} maxBarSize={30} />
            </BarChart>
          </ResponsiveContainer>
          <div style={{ display: "flex", gap: 16, marginTop: 4, marginBottom: 14, fontSize: 11.5, color: COLORS.inkMuted }}>
            <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 9, height: 9, borderRadius: 2, background: COLORS.teal, display: "inline-block" }} /> Vendas fechadas</span>
            <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 9, height: 9, borderRadius: 2, background: COLORS.amber, display: "inline-block" }} /> Instalações executadas</span>
          </div>
        </div>
      )}

      {importLog.length > 0 && (
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "16px 18px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 10 }}>
            <History size={14} color={COLORS.inkMuted} />
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 13.5, fontWeight: 600 }}>Histórico de importações</div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {importLog.slice(0, 6).map((log, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, color: COLORS.inkSoft, padding: "4px 0" }}>
                <span style={{ fontWeight: 500 }}>{log.label}</span>
                <span style={{ color: COLORS.inkMuted }}>{new Date(log.date).toLocaleDateString("pt-BR")} · {log.added} novo(s), {log.updated} atualizado(s)</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <p style={{ fontSize: 11.5, color: COLORS.inkMuted, marginTop: 20, textAlign: "center" }}>
        O mês de cada OS usa a data agendada (início programado). "Pontualidade" considera iniciada no prazo quando a execução
        começou em até 4h do horário agendado — ajuste esse critério se vocês usam um SLA diferente. Quando mais de um técnico
        está na mesma OS, eles aparecem juntos como uma única combinação na tabela (não contam em dobro).
      </p>
    </div>
  );
}
